'use strict';

// MODULES //

var sqrt = require( '@stdlib/math/base/special/sqrt' );
var min = require( '@stdlib/math/base/special/min' );
var rank = require( './rank.js' );


// MAIN //

/**
* Computes the source factorization of a fully prevalidated band.
* @private
* @param {string|integer} uplo - selected triangle
* @param {NonNegativeInteger} N - matrix order
* @param {NonNegativeInteger} KD - bandwidth
* @param {Float64Array} AB - compact band storage
* @param {integer} r - band row stride
* @param {integer} c - band column stride
* @param {integer} o - band offset
* @returns {integer} INFO
*/
function base( uplo, N, KD, AB, r, c, o ) {
	var diagonal;
	var alpha;
	var count;
	var index;
	var value;
	var j;
	var q;
	for ( j = 0; (j < N); j += 1 ) {
		diagonal = ((o+(( (uplo === 121) ) ? (KD*r) : 0))+(j*c));
		value = AB[ diagonal ];
		if ( (value <= 0) ) {
			return (j+1);
		}
		value = sqrt( value );
		AB[diagonal] = value;
		count = min( KD, ((N-j)-1) );
		if ( (count !== 0) ) {
			alpha = (1/value);
			if ( (alpha !== 1) ) {
				for ( q = 0; (q < count); q += 1 ) {
					index = ( (uplo === 121) ) ? ((o+((((KD-1)-q))*r))+((((j+1)+q))*c)) : ((o+(((1+q))*r))+(j*c));
					AB[index] = (alpha*AB[index]);
				}
			}
			rank( uplo, KD, j, count, AB, r, c, o );
		}
	}
	return 0;
}


// EXPORTS //

module.exports = base;
